-- Phase 2 data correction.
--> statement-breakpoint
-- The demo question bank was written by AI for demonstration. It was previously tagged with
--> statement-breakpoint
-- stand-in categories (including VERIFIED_PYQ) and linked to fictional demo papers. That is
--> statement-breakpoint
-- corrected here: every demo question becomes AI_SUPPLEMENTARY and unreviewed, and the fictional
--> statement-breakpoint
-- papers and their links are removed so no demo question carries any exam provenance.
--> statement-breakpoint
UPDATE questions SET source_type = 'AI_SUPPLEMENTARY', verification_status = 'UNVERIFIED', verified_at = NULL, verified_by = NULL, verification_notes = 'Demo question written by AI for demonstration. Not a previous-year question and not reviewed by an editor.', frequency_count = 0, answer_source = 'AI', mapping_status = 'CONFIRMED', mapping_source = 'author' WHERE is_demo = 1;
--> statement-breakpoint
DELETE FROM question_sources WHERE paper_id IN (SELECT id FROM papers WHERE is_demo = 1);
--> statement-breakpoint
UPDATE import_batches SET paper_id = NULL WHERE paper_id IN (SELECT id FROM papers WHERE is_demo = 1);
--> statement-breakpoint
DELETE FROM papers WHERE is_demo = 1;
--> statement-breakpoint
-- Any non-demo question marked as a verified PYQ without a linked board paper that has a year loses its verified status.
--> statement-breakpoint
UPDATE questions SET verification_status = 'UNVERIFIED', verified_at = NULL, verified_by = NULL, verification_notes = 'Set to unverified by migration 0002: no linked board exam paper with a year.' WHERE is_demo = 0 AND source_type = 'VERIFIED_PYQ' AND verification_status = 'VERIFIED' AND id NOT IN (SELECT qs.question_id FROM question_sources qs JOIN papers p ON p.id = qs.paper_id WHERE p.is_demo = 0 AND p.paper_type = 'BOARD_EXAM' AND p.year IS NOT NULL);
--> statement-breakpoint
UPDATE questions SET answer_source = 'EDITOR' WHERE is_demo = 0 AND answer_source = 'NONE' AND answer_text <> '';
--> statement-breakpoint
UPDATE papers SET status = 'VERIFIED' WHERE is_demo = 0;
--> statement-breakpoint

